function comparisonMetricSvg(label,previousRows,currentRows,valueOf,unit,color){const rows=[previousRows,currentRows],maxLen=Math.max(...rows.map(items=>items.length),1),values=rows.flat().map(valueOf).filter(Number.isFinite),min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.2,.2),yMin=min-pad,yMax=max+pad,W=760,H=180,p={l:42,r:18,t:18,b:24},x=i=>p.l+i*(W-p.l-p.r)/Math.max(maxLen-1,1),y=value=>p.t+(yMax-value)*(H-p.t-p.b)/(yMax-yMin),line=(items,stroke,dash)=>{const points=items.map((item,i)=>`${x(i)},${y(valueOf(item))}`).join(' ');return `<polyline points="${points}" fill="none" stroke="${stroke}" stroke-width="${dash?2:2.5}" stroke-linecap="round" stroke-linejoin="round"${dash?' stroke-dasharray="6 4"':''}/>`};let svg=`<div class="comparison-metric-chart" data-comparison-chart="${label}"><div class="comparison-metric-heading"><strong>${label}</strong><span>${unit}</span></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="이전 프로그램과 현재 프로그램의 ${label} 비교"><line x1="${p.l}" y1="${H-p.b}" x2="${W-p.r}" y2="${H-p.b}" stroke="#dfe7e1"/><line x1="${p.l}" y1="${p.t}" x2="${p.l}" y2="${H-p.b}" stroke="#dfe7e1"/>`;for(let i=0;i<3;i++){const yy=p.t+i*(H-p.t-p.b)/2;svg+=`<line x1="${p.l}" y1="${yy}" x2="${W-p.r}" y2="${yy}" stroke="#edf1ed"/><text x="0" y="${yy+4}" fill="#9aa69e" font-size="10">${(yMax-(yMax-yMin)*i/2).toFixed(1)}</text>`}if(previousRows.length)svg+=line(previousRows,'#9aa69e',false);if(currentRows.length)svg+=line(currentRows,color,true);svg+='</svg><div class="comparison-chart-legend"><span><i class="previous-key"></i>이전 프로그램</span><span><i class="current-key"></i>현재 프로그램</span></div></div>';return svg}
function buildProgramComparisonDetails(previousRows,currentRows){const metrics=[['체중',record=>Number(record.weight),'kg','#2d704a'],['체지방률',record=>fatPercent(record),'%','#e98d4f'],['근육량',record=>Number(record.muscle),'kg','#5b78b8']];const first=rows=>rows[0],last=rows=>rows.at(-1),value=(rows,metric,index)=>rows.length?metric[1](index?last(rows):first(rows)):null,card=metric=>{const previousStart=value(previousRows,metric,0),previousEnd=value(previousRows,metric,1),currentStart=value(currentRows,metric,0),currentEnd=value(currentRows,metric,1);return `<article class="comparison-summary-card"><strong>${metric[0]}</strong><div><span>이전</span><b>${previousStart===null?'-':previousStart.toFixed(1)} → ${previousEnd===null?'-':previousEnd.toFixed(1)}${metric[2]}</b></div><div><span>현재</span><b>${currentStart===null?'-':currentStart.toFixed(1)} → ${currentEnd===null?'-':currentEnd.toFixed(1)}${metric[2]}</b></div></article>`};const deltaCard=metric=>{const previousDelta=previousRows.length?metric[1](last(previousRows))-metric[1](first(previousRows)):null,currentDelta=currentRows.length?metric[1](last(currentRows))-metric[1](first(currentRows)):null,deltaUnit=metric[0]==='체지방률'?'%p':metric[2];return `<article class="comparison-delta-card"><strong>${metric[0]} 변화량</strong><div><span>이전</span><b>${previousDelta===null?'-':signedDelta(previousDelta)}${deltaUnit}</b></div><div><span>현재</span><b>${currentDelta===null?'-':signedDelta(currentDelta)}${deltaUnit}</b></div></article>`};return `<div class="comparison-summary-grid">${metrics.map(card).join('')}</div><div class="comparison-delta-grid">${metrics.map(deltaCard).join('')}</div><div class="comparison-chart-tabs" role="tablist" aria-label="비교 지표 선택">${metrics.map((metric,index)=>`<button type="button" class="${index?'':'active'}" data-comparison-tab="${metric[0]}" role="tab">${metric[0]}</button>`).join('')}</div><div class="comparison-metric-charts">${metrics.map(metric=>comparisonMetricSvg(metric[0],previousRows,currentRows,metric[1],metric[2],metric[3])).join('')}</div>`}
setTimeout(()=>{const openArchiveWithTabs=openProgramArchive;openProgramArchive=id=>{openArchiveWithTabs(id);const chart=$('#archiveDialogBody .archive-comparison-chart');if(!chart)return;const tabs=[...chart.querySelectorAll('[data-comparison-tab]')],panels=[...chart.querySelectorAll('[data-comparison-chart]')],activate=label=>{tabs.forEach(tab=>tab.classList.toggle('active',tab.dataset.comparisonTab===label));panels.forEach(panel=>{panel.hidden=panel.dataset.comparisonChart!==label})};tabs.forEach(tab=>{tab.onclick=()=>activate(tab.dataset.comparisonTab)});if(tabs[0])activate(tabs[0].dataset.comparisonTab)}},0);
setTimeout(()=>{const dialog=$('#programPairDialog'),selectA=$('#programPairA'),selectB=$('#programPairB'),body=$('#programPairComparison');if(!dialog||!selectA||!selectB)return;const getPrograms=()=>[{id:'current',label:`현재 프로그램 · ${state.startDate.replaceAll('-','.')}`,records:scopedRecords().slice().sort((a,b)=>a.date.localeCompare(b.date))},...state.programs.slice().reverse().map(program=>({id:program.id,label:`${program.startDate.replaceAll('-','.')} 프로그램`,records:program.records.slice().sort((a,b)=>a.date.localeCompare(b.date))}))];const bindTabs=()=>{const tabs=[...body.querySelectorAll('[data-comparison-tab]')],panels=[...body.querySelectorAll('[data-comparison-chart]')];tabs.forEach((tab,index)=>{tab.onclick=()=>{tabs.forEach(item=>item.classList.toggle('active',item===tab));panels.forEach((panel,panelIndex)=>{panel.hidden=panelIndex!==index})}});if(tabs[0])tabs[0].click()};const refresh=()=>{const programs=getPrograms(),options=programs.map(program=>`<option value="${program.id}">${program.label}</option>`).join('');selectA.innerHTML=options;selectB.innerHTML=options;if(programs.length>1){selectA.value=programs[1].id;selectB.value=programs[0].id}renderPair()};const renderPair=()=>{const programs=getPrograms(),left=programs.find(program=>program.id===selectA.value),right=programs.find(program=>program.id===selectB.value);if(!left||!right){body.innerHTML='<p class="empty-records">비교할 프로그램을 선택하세요.</p>';return}if(left.id===right.id){body.innerHTML='<p class="pair-warning">서로 다른 프로그램을 선택하세요.</p>';return}body.innerHTML=buildProgramComparisonDetails(left.records,right.records).replaceAll('이전',left.label).replaceAll('현재',right.label);bindTabs()};$('#comparePrograms').onclick=()=>{refresh();dialog.showModal()};[selectA,selectB].forEach(select=>select.onchange=renderPair);$('#closeProgramPair').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===event.currentTarget)dialog.close()})},0);
