function renderRecordGapNotice(){const notice=$('#recordGapNotice'),rows=scopedRecords().slice().sort((a,b)=>a.date.localeCompare(b.date));if(!rows.length){notice.hidden=true;return}const gaps=[];for(let i=1;i<rows.length;i++){const days=Math.floor((new Date(`${rows[i].date}T00:00:00`)-new Date(`${rows[i-1].date}T00:00:00`))/86400000);if(days>=7)gaps.push(days)}const today=new Date();today.setHours(0,0,0,0);const lastDate=new Date(`${rows.at(-1).date}T00:00:00`),referenceEnd=state.endDate&&new Date(`${state.endDate}T00:00:00`)<today?new Date(`${state.endDate}T00:00:00`):today,daysSinceLast=Math.floor((referenceEnd-lastDate)/86400000);if(daysSinceLast>=7||gaps.length){notice.hidden=false;notice.textContent=daysSinceLast>=7?`최근 기록 후 ${daysSinceLast}일이 지났습니다. 현재 통계는 참고용으로 확인하세요.`:`측정 기록 사이에 ${Math.max(...gaps)}일 공백이 있습니다. 주차 추세 해석에 유의하세요.`}else notice.hidden=true}
