setTimeout(()=>{const baseWeeklyHistoryChart=renderWeeklyHistoryChart;renderWeeklyHistoryChart=()=>{baseWeeklyHistoryChart();const svg=$('#weeklyHistoryChart'),polyline=svg?.querySelector('polyline');if(!polyline)return;const points=polyline.getAttribute('points').trim().split(/\s+/).map(point=>point.split(',').map(Number)).filter(point=>point.length===2&&point.every(Number.isFinite));if(points.length<2)return;const meanX=points.reduce((sum,point)=>sum+point[0],0)/points.length,meanY=points.reduce((sum,point)=>sum+point[1],0)/points.length,slope=points.reduce((sum,point)=>sum+(point[0]-meanX)*(point[1]-meanY),0)/points.reduce((sum,point)=>sum+(point[0]-meanX)**2,0),intercept=meanY-slope*meanX,trend=document.createElementNS('http://www.w3.org/2000/svg','line');trend.setAttribute('x1',String(points[0][0]));trend.setAttribute('y1',String(slope*points[0][0]+intercept));trend.setAttribute('x2',String(points.at(-1)[0]));trend.setAttribute('y2',String(slope*points.at(-1)[0]+intercept));trend.setAttribute('stroke','#e98d4f');trend.setAttribute('stroke-width','2');trend.setAttribute('stroke-dasharray','7 5');trend.setAttribute('data-trend-line','true');svg.insertBefore(trend,polyline);const wrap=svg.closest('.weekly-history-chart');if(wrap&&!wrap.querySelector('.weekly-trend-legend'))wrap.insertAdjacentHTML('beforeend','<div class="weekly-trend-legend"><span><i class="weekly-value-key"></i>측정값</span><span><i class="weekly-trend-key"></i>추세선</span></div>')}} ,0);
