$('#exportData').onclick=()=>{const today=fmt(new Date()),payload={version:2,exportedAt:new Date().toISOString(),startDate:state.startDate,endDate:state.endDate||'',programId:state.programId,programs:state.programs,lastProgramTransition:state.lastProgramTransition||null,lastStageTransition:state.lastStageTransition||null,height:state.height,stage:state.stage,repeat:state.repeat,records:state.records,fastingDays:state.fastingDays,decisionChecks:state.decisionChecks};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`switchon-${today}.json`;link.click();URL.revokeObjectURL(link.href)};
